const $=s=>document.querySelector(s);
const icons={arrow:'M5 12h14m-6-6 6 6-6 6',up:'M6 18 18 6M6 6h12v12',check:'m5 12 4 4L19 6',book:'M12 5c-4-3-8-2-9-1v15c3-2 6-2 9 0 3-2 6-2 9 0V4c-3-1-6-2-9 1Zm0 0v14',notebook:'M6 3h14v18H6zM3 7h6M3 12h6M3 17h6M12 7h5M12 11h5',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',file:'M14 2H5v20h14V7Zm0 0v6h5M8 12h8M8 16h8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',info:'M12 11v6M12 7v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',pause:'M8 5v14M16 5v14',play:'m8 4 12 8-12 8Z',edit:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Zm-4 10 3 3 5-6',plus:'M12 4v16M4 12h16',layers:'m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
let state={version:2,notes:[],completed:[],drafts:{},quiz:{},checks:[],last:0,resume:null,noteDraft:{title:'',body:'',stage:0}},storageAvailable=true;
function sanitize(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.notes)||!Array.isArray(raw.completed))throw Error('Invalid workspace');const result={...state,notes:raw.notes.filter(n=>n&&typeof n.title==='string'&&typeof n.body==='string'&&Number.isInteger(n.stage)&&n.stage>=0&&n.stage<9).map(n=>({id:typeof n.id==='string'?n.id:uid(),title:n.title.slice(0,150),body:n.body.slice(0,100000),stage:n.stage,created:typeof n.created==='string'?n.created:new Date().toISOString(),updated:typeof n.updated==='string'?n.updated:null})),completed:[...new Set(raw.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<9))],drafts:{},quiz:{},checks:[],last:Number.isInteger(raw.last)&&raw.last>=0&&raw.last<9?raw.last:0,noteDraft:{title:'',body:'',stage:0}};for(let i=0;i<9;i++){if(typeof raw.drafts?.[i]==='string')result.drafts[i]=raw.drafts[i].slice(0,100000);if(Number.isInteger(raw.quiz?.[i])&&raw.quiz[i]>=0&&raw.quiz[i]<3)result.quiz[i]=raw.quiz[i]}if(Array.isArray(raw.checks))result.checks=[...new Set(raw.checks.filter(x=>typeof x==='string'&&/^\d-[0-2]$/.test(x)))];if(raw.noteDraft&&typeof raw.noteDraft.title==='string'&&typeof raw.noteDraft.body==='string')result.noteDraft={title:raw.noteDraft.title.slice(0,150),body:raw.noteDraft.body.slice(0,100000),stage:Number.isInteger(raw.noteDraft.stage)&&raw.noteDraft.stage>=0&&raw.noteDraft.stage<9?raw.noteDraft.stage:0};if(raw.editDraft&&typeof raw.editDraft.id==='string'&&typeof raw.editDraft.title==='string'&&typeof raw.editDraft.body==='string'&&Number.isInteger(raw.editDraft.stage)&&raw.editDraft.stage>=0&&raw.editDraft.stage<9)result.editDraft={id:raw.editDraft.id,title:raw.editDraft.title.slice(0,150),body:raw.editDraft.body.slice(0,100000),stage:raw.editDraft.stage};result.resume=raw.resume&&Number.isInteger(raw.resume.lesson)&&raw.resume.lesson>=0&&raw.resume.lesson<9&&['learn','example','write','check'].includes(raw.resume.step)?{lesson:raw.resume.lesson,step:raw.resume.step}:null;return result}
try{const saved=localStorage.getItem('rrh-v2');if(saved)state=sanitize(JSON.parse(saved));else{const old=localStorage.getItem('rrh-v1');if(old)state=sanitize(JSON.parse(old))}}catch{storageAvailable=false}
if(state.editDraft&&!state.notes.some(n=>n.id===state.editDraft.id))state.editDraft=null;
let toastTimer,editing=state.editDraft?.id||null,noteQuery='',academyFilter='all',academyQuery='',toolFilter='All',toolQuery='',workspaceTab='notes',pendingImport=null,deleted=null;
function toast(message,undo=false){clearTimeout(toastTimer);$('#toast').innerHTML=esc(message)+(undo?'<button data-action="undo">Undo</button>':'');$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),undo?12000:4500)}
function save(){try{localStorage.setItem('rrh-v2',JSON.stringify(state));storageAvailable=true;return true}catch{storageAvailable=false;toast('Storage is unavailable. Download a backup before closing this page.');return false}}
function nextLesson(){return course.findIndex((_,i)=>!state.completed.includes(i))<0?8:course.findIndex((_,i)=>!state.completed.includes(i))}
function dial(){const p=Math.round(state.completed.length/9*100);return `<div class="progress-dial" style="--p:${p}" aria-label="${p} percent complete"><span>${p}%</span></div>`}
function phaseArt(i){return `<div class="phase-art sculpture" data-sculpture="${i}" aria-hidden="true"><img src="rei-mark.svg" alt="" class="sculpture-fallback"><canvas></canvas><span class="sculpture-caption">${['01 / THE QUESTION','02 / THE CONNECTION','03 / THE STRUCTURE'][i]}</span></div>`}
function heading(kicker,title,description,actions=''){return `<div class="page-heading page-heading-row"><div class="heading-grid" aria-hidden="true"></div><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function readings(){return `<div class="reading-links"><h3>Keep learning from trusted guides</h3><div>${furtherReading.map(r=>`<a class="reading-link" href="${r.url}" target="_blank" rel="noopener noreferrer"><small>${r.org}</small><h4>${r.title} ↗</h4><p>${r.desc}</p></a>`).join('')}</div><p class="site-note">External guides offer additional context. Follow your supervisor’s and institution’s requirements for your own project.</p></div>`}
function home(){return `<section class="observatory container"><div class="observatory-intro"><p class="eyebrow"><span class="live-dot"></span> REI / THE RESEARCH OBSERVATORY</p><h1>A new dimension<span> for your research.</span></h1><div class="intro-bottom"><p>Learn the method. Connect the evidence. Shape your next discovery. <br>A personal studio for research that goes somewhere.</p><a class="button light" href="#lesson/${nextLesson()}">${state.completed.length?'Continue researching':'Enter your research space'} ${icon('up')}</a></div></div><div class="discovery-stage" data-phase="0"><div class="stage-grid" aria-hidden="true"></div><div class="stage-coordinate">REI / THE DISCOVERY ENGINE <span>EXPLORE · CONNECT · CREATE</span></div><div class="universe" id="universe"><canvas id="cosmos" aria-hidden="true"></canvas><div class="orb-tag"><span class="live-dot"></span> AN INTERACTIVE FIELD OF POSSIBILITY</div><button class="scene-pause icon-button" id="motion" aria-label="Pause animation" aria-pressed="false">${icon('pause')}</button></div><div class="atlas-panel"><p class="eyebrow">YOUR DISCOVERY ATLAS</p><h2 id="atlas-title">Find your<br>starting point.</h2><p id="atlas-description">Turn the things you notice into a question worth exploring.</p><div class="atlas-selector" role="group" aria-label="Explore research phases">${phases.map((p,i)=>`<button data-atlas="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${p.label}${icon('arrow')}</button>`).join('')}</div><a id="atlas-link" class="text-link" href="#lesson/0">Explore foundations ${icon('up')}</a></div><a class="floating-evidence" href="#notebook"><div><span class="live-dot"></span> YOUR PERSONAL WORKSPACE ${icon('up')}</div><h3>Good ideas deserve<br>a place to grow.</h3><div class="evidence-lines" aria-hidden="true"><span></span><span></span><span></span></div><footer>${icon('notebook')} ${state.notes.length} saved ${state.notes.length===1?'idea':'ideas'}<span>Open notebook →</span></footer></a><div class="atlas-bottom"><span>01 — 09 <b>A COMPLETE RESEARCH JOURNEY</b></span><span>Move your pointer to explore the field ${icon('plus')}</span></div></div><div class="research-entry"><div><span class="eyebrow">INTRODUCING YOUR RESEARCH STUDIO</span><h2>Give your evidence a place to connect.</h2><p>Organize papers, compare findings, and build a source-linked proposal.</p></div><a href="#research" class="button light">Open research studio ${icon('up')}</a></div><div class="journey-dock"><div>${dial()}<span><strong>${state.completed.length? 'Welcome back to your work.':'Every discovery starts somewhere.'}</strong><small>${state.completed.length} of 9 milestones complete</small></span></div><div class="dock-track" aria-label="Milestone progress">${course.map((c,i)=>`<a href="#lesson/${i}" class="${state.completed.includes(i)?'done':''}" aria-label="${esc(c.title)}${state.completed.includes(i)?', complete':''}"><span>${String(i+1).padStart(2,'0')}</span></a>`).join('')}</div><a class="text-link" href="#journey">Your roadmap ${icon('arrow')}</a></div></section><section class="pathways-section container"><div class="section-top"><div><p class="eyebrow">01 / A CONNECTED PROCESS</p><h2>Follow the curiosity.<br><span>Build the clarity.</span></h2></div><p>A little structure opens up a lot of possibility. Move through three connected phases at your own pace.</p></div><div class="pathway-editorial">${phases.map((p,i)=>`<a class="pathway-tile pathway-${i}" href="#lesson/${i*3}"><div class="pathway-top"><span>0${i+1} / ${p.label}</span>${icon('up')}</div>${phaseArt(i)}<div class="pathway-caption"><h3>${p.name}</h3><p>${p.desc}</p><span>EXPLORE MILESTONES ${i*3+1}—${i*3+3} ${icon('arrow')}</span></div></a>`).join('')}</div></section><section class="workspace-showcase"><div class="container"><div class="section-top"><div><p class="eyebrow">02 / THE RESEARCH WORKSPACE</p><h2>Less scattered.<br><span>More connected.</span></h2></div><a class="button secondary" href="#notebook">Open your workspace ${icon('up')}</a></div><div class="workspace-mosaic"><a href="#notebook/draft" class="mosaic-draft"><div class="mosaic-label">${icon('file')} THE BIG PICTURE ${icon('up')}</div><div class="paper-stack" aria-hidden="true"><div class="paper-under"></div><div class="paper-front"><span>REI / WORKING DRAFT</span><h3>Your ideas,<br>taking shape.</h3><div class="paper-rule"></div><b>01 &nbsp; THE RESEARCH QUESTION</b><i></i><i></i><b>02 &nbsp; THE EVIDENCE</b><i></i><i></i><div class="paper-stamp">WORK IN<br>PROGRESS ✦</div></div></div><div class="mosaic-caption"><h3>One proposal. All your thinking.</h3><p>Your lesson exercises come together in a single working draft.</p></div></a><a href="#toolkit" class="mosaic-toolkit"><div class="mosaic-label">${icon('layers')} TOOLS FOR THE PROCESS ${icon('up')}</div><div class="tool-sculpture">${phaseArt(2)}</div><h3>A head start,<br>at every step.</h3><p>Templates and checklists that turn a blank page into a next move.</p></a><a href="#notebook/readiness" class="mosaic-ready"><div><p class="eyebrow">READY FOR THE NEXT STEP?</p><h3>Make every detail count.</h3><p>A 27-point review to help you refine your proposal.</p></div><div class="readiness-art" aria-hidden="true">${icon('check')}</div>${icon('up')}</a></div></div></section><section class="academy-editorial container"><div><p class="eyebrow">03 / LEARN BY DOING</p><h2>Knowledge is<br>only the beginning.</h2><p>Work through an example. Try an exercise. Leave with something you can use in your own research.</p><a class="button light" href="#academy">Explore the academy ${icon('up')}</a></div><div class="academy-list">${[0,2,4,7].map(i=>`<a href="#lesson/${i}"><span>0${i+1}</span><div><small>${phases[course[i].phase].label} / ${course[i].time} MIN</small><h3>${course[i].title}</h3></div>${icon('up')}</a>`).join('')}<a class="all-lessons" href="#academy">View all nine milestones ${icon('arrow')}</a></div></section><section class="final-portal container"><p class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</p><h2>Stay curious.<br><span>Go somewhere new.</span></h2><a class="button light" href="#lesson/${nextLesson()}">Let’s begin ${icon('up')}</a><div class="portal-rings" aria-hidden="true"></div></section>`}
function journey(){return `<div class="container">${heading('YOUR RESEARCH ROADMAP','From a spark to a proposal.','Nine connected milestones. Follow the sequence, or revisit the step your project needs today.')}<div class="page-body"><div class="journey-summary">${dial()}<div><h3>${state.completed.length===9?'Your first pass is complete. Keep refining.':`${state.completed.length} of 9 milestones complete`}</h3><p>${Object.values(state.drafts).filter(x=>x.trim()).length} saved exercise drafts · Your progress stays on this device.</p></div><a class="button primary small" href="#lesson/${nextLesson()}">${state.completed.length===9?'Review your proposal':'Continue learning'} ${icon('arrow')}</a></div><div class="roadmap">${phases.map((p,j)=>`<section class="roadmap-column">${phaseArt(j)}<span class="pill ${p.color}">PHASE 0${j+1} · ${p.label}</span><h2>${p.name}</h2><p>${p.desc}</p><div class="roadmap-steps">${course.map((c,i)=>c.phase===j?`<a class="roadmap-step" href="#lesson/${i}"><span class="step-number ${state.completed.includes(i)?'done':''}">${state.completed.includes(i)?icon('check'):String(i+1).padStart(2,'0')}</span><div><h3>${stages[i][0]}</h3><p>${state.completed.includes(i)?'Complete · Revisit lesson':state.drafts[i]?.trim()?'Draft started · Continue':c.output}</p></div>${icon('arrow')}</a>`:'').join('')}</div></section>`).join('')}</div><div class="info-line">${icon('info')}<div><strong>Research is rarely a straight line.</strong> A new source may change your question. A practical constraint may reshape your methods. Revisit earlier milestones as your understanding grows.</div></div></div></div>`}
function lessonCards(){const entries=course.map((c,i)=>({c,i})).filter(({c,i})=>(academyFilter==='all'||c.phase===+academyFilter)&&(c.title+' '+c.subtitle+' '+stages[i][0]).toLowerCase().includes(academyQuery.toLowerCase()));return entries.length?entries.map(({c,i})=>`<a class="lesson-card" href="#lesson/${i}"><div class="lesson-cover ${phases[c.phase].color}"><span class="cover-number">${String(i+1).padStart(2,'0')}</span>${phaseArt(c.phase)}${state.completed.includes(i)?'<span class="completed-label">✓ Completed</span>':''}</div><div class="lesson-card-content"><span class="eyebrow">${phases[c.phase].label} / LESSON ${String(i+1).padStart(2,'0')}</span><h3>${c.title}</h3><p>${c.subtitle}</p><div class="lesson-card-bottom"><span>${c.time} min activity · Exercise included</span>${icon('arrow')}</div></div></a>`).join(''):'<div class="no-results"><h3>No lessons match that search.</h3><p>Try “question,” “methods,” or another phase.</p></div>'}
function academy(){return `<div class="container">${heading('RESEARCH ACADEMY','Build understanding. Then build your study.','Nine practical lessons with worked examples, writing exercises, and knowledge checks. Suggested activity times are flexible.')}<div class="page-body"><div class="toolbar"><div class="tabs" aria-label="Filter lessons">${[['all','All lessons'],...phases.map((p,i)=>[i,p.label[0]+p.label.slice(1).toLowerCase()])].map(([v,l])=>`<button data-course-filter="${v}" aria-pressed="${String(v)===String(academyFilter)}">${l}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="lesson-search" type="search" placeholder="Find a lesson…" aria-label="Search lessons" value="${esc(academyQuery)}"></label></div><div class="lesson-grid" id="lesson-grid">${lessonCards()}</div>${readings()}</div></div>`}
function lesson(i,step='learn'){
 const names={learn:'Learn the concept',example:'Study an example',write:'Write your draft',check:'Check understanding'};if(!names[step])step='learn';state.resume={lesson:i,step};
 const c=course[i],template=document.createElement('template');template.innerHTML=lessonFull(i);const root=template.content,main=root.querySelector('.lesson-main'),content=root.querySelector('.lesson-content'),exercise=root.querySelector('.exercise');
 main.dataset.step=step;main.dataset.phase=c.phase;const originalTitle=root.querySelector('.lesson-title');originalTitle.insertAdjacentHTML('afterbegin',`<div class="field-edition"><span>RESEARCH FIELDNOTES</span><span>VOL. ${String(i+1).padStart(2,'0')} / ${phases[c.phase].label}</span></div>`);originalTitle.querySelector('.lesson-title-meta').insertAdjacentHTML('beforeend',`<span class="step-location">${Object.keys(names).indexOf(step)+1} / 4 · ${names[step]}</span>`);
 const nav=document.createElement('nav');nav.className='lesson-flow';nav.setAttribute('aria-label','Lesson steps');nav.innerHTML=Object.entries(names).map(([key,label],n)=>`<a href="#lesson/${i}${key==='learn'?'':'/'+key}" ${step===key?'aria-current="page"':''}><span>0${n+1}</span><strong>${label}</strong>${icon(key==='check'?'check':'arrow')}</a>`).join('');originalTitle.after(nav);
 const examples=content.querySelector('.example'),pitfall=content.querySelector('.pitfall'),steps=content.querySelector('ol.steps').closest('section'),quiz=exercise.querySelector('.quiz'),completion=exercise.querySelector('.completion-bar'),actions=exercise.querySelector('.actions');
 if(step==='learn'){examples.remove();pitfall.remove();steps.remove();exercise.remove();content.insertAdjacentHTML('afterbegin',`<div class="reading-intro"><span>THE CONCEPT</span><p>${c.subtitle}</p></div>`)}
 if(step==='example'){content.innerHTML='';content.append(examples,pitfall);exercise.remove();examples.querySelector('h3').outerHTML='<h2>From a starting point to a clearer direction</h2>';content.insertAdjacentHTML('afterbegin','<div class="reading-intro"><span>WORKED EXAMPLE</span><p>Compare the two versions, then read why the change makes the research more focused.</p></div>')}
 if(step==='write'){content.remove();quiz.remove();completion.remove();actions.remove();exercise.prepend(steps);exercise.querySelector('textarea').rows=12}
 if(step==='check'){content.remove();exercise.innerHTML='';exercise.append(quiz,completion);exercise.insertAdjacentHTML('afterbegin',`<div class="reading-intro"><span>REVIEW YOUR WORK</span><h2>Test the idea. Then move forward.</h2><p>Answer the question below. You can complete this milestone once you have saved a draft and selected the correct answer.</p><a class="draft-review-link" href="#lesson/${i}/write">${state.drafts[i]?.trim()?'Review your saved draft':'Write your draft first'} ${icon('up')}</a></div>`)}
 if(step==='check'){const intro=exercise.querySelector('.reading-intro');intro.classList.add('review-context');intro.querySelector('h2').textContent='A moment of clarity.';intro.querySelector('p').textContent='Choose the answer that best applies the lesson. Use the feedback to refine your reasoning before moving on.';const visual=originalTitle.querySelector('.lesson-visual');intro.append(visual);intro.insertAdjacentHTML('beforeend','<div class="review-caption"><span>OBSERVE</span><i></i><span>REASON</span><i></i><span>DECIDE</span></div>');quiz.querySelector('h3').textContent='Make your choice';quiz.querySelectorAll('label').forEach((label,n)=>{label.insertAdjacentHTML('afterbegin','<span class="answer-letter" aria-hidden="true">'+String.fromCharCode(65+n)+'</span>')})}
 if(step==='write'){const preparation=exercise.querySelector('section');preparation.classList.add('writing-brief');exercise.querySelector('textarea').setAttribute('placeholder',c.placeholder);exercise.insertAdjacentHTML('afterbegin','<div class="studio-caption"><span>THE WRITING STUDIO</span><span>YOUR IDEAS / YOUR WORDS</span></div>')}
 if(step==='learn'){content.querySelectorAll(':scope > section').forEach((section,n)=>section.insertAdjacentHTML('afterbegin','<span class="section-marker" aria-hidden="true">'+String(n+1).padStart(2,'0')+'</span>'))}
 const keys=Object.keys(names),idx=keys.indexOf(step);main.insertAdjacentHTML('beforeend',`<div class="lesson-pagination"><a href="${idx?'#lesson/'+i+(idx===1?'':'/'+keys[idx-1]):'#academy'}">${icon('arrow')} ${idx?names[keys[idx-1]]:'Back to academy'}</a><span>STEP ${idx+1} OF 4</span>${idx<3?`<a class="button primary" href="#lesson/${i}/${keys[idx+1]}">${names[keys[idx+1]]} ${icon('arrow')}</a>`:`<a class="button secondary" href="${i<8?'#lesson/'+(i+1):'#notebook/draft'}">${i<8?'Next milestone':'Review proposal'} ${icon('arrow')}</a>`}</div>`);
 return template.innerHTML;
}
function resourcePage(id){const r=resources.find(x=>x.id===id);if(!r)return '<div class="container section"><h1>Resource not found</h1><a href="#toolkit">Return to toolkit</a></div>';return `<div class="container"><div class="breadcrumbs"><a href="#toolkit">Toolkit</a><span>/</span><span>${r.category}</span></div>${heading(r.category+' / '+r.format,r.name,r.desc)}<div class="detail-layout"><aside class="detail-guide"><div class="detail-symbol">${icon('layers')}</div><h2>Use this resource</h2><p>${r.use}</p><button class="button primary" data-download="${r.id}">Download ${r.format} ${icon('download')}</button><p class="meta">Editable file · Adapt it to your study</p></aside><article class="detail-body"><p class="eyebrow">WHAT’S INSIDE</p><h2>A structure for your next step</h2><ol class="resource-contents">${r.preview.map((x,i)=>`<li><span>0${i+1}</span><p>${x}</p></li>`).join('')}</ol><details class="file-detail"><summary>Read the complete template</summary><pre class="resource-preview">${esc(r.content)}</pre></details><a class="text-link" href="#toolkit">Explore other resources ${icon('arrow')}</a></article></div></div>`}
function workshopPage(i){const p=phases[i];return `<div class="container"><div class="breadcrumbs"><a href="#seminars">Workshops</a><span>/</span><span>${p.name}</span></div>${heading('SELF-GUIDED SESSION / 45–60 MIN',p.name,'A focused session with a clear outcome. Work independently or discuss each activity with a peer.')}<div class="detail-layout"><aside class="detail-guide">${phaseArt(i)}<h2>Before you begin</h2><p>Bring your current research idea, your notes, and any sources you have read.</p><button class="button primary" data-workshop-download="${i}">Download agenda ${icon('download')}</button><p class="meta">No registration required · No recording</p></aside><article class="detail-body workshop-agenda"><p class="eyebrow">YOUR SESSION PLAN</p><section><span>01 / 5 MIN</span><h2>Set an intention</h2><p>Write down one thing you want to understand by the end of the session.</p></section>${course.slice(i*3,i*3+3).map((c,n)=>`<section><span>0${n+2} / 10–15 MIN</span><h2>${c.title}</h2><p>${c.steps[0]}</p><p><strong>Your output:</strong> ${c.output}</p><a class="text-link" href="#lesson/${i*3+n}/write">Open this activity ${icon('up')}</a></section>`).join('')}<section><span>05 / 10 MIN</span><h2>Review and choose a next step</h2><p>What changed in your thinking? Record one uncertainty and one specific action to discuss with your supervisor.</p></section></article></div></div>`}

function lessonFull(i){const c=course[i],isDone=state.completed.includes(i);state.last=i;save();return `<div class="container"><div class="breadcrumbs"><a href="#academy">Academy</a><span>/</span><span>${phases[c.phase].name}</span><span>/</span><span>Lesson ${i+1}</span></div><div class="lesson-layout"><aside class="lesson-sidebar"><h3>Your learning path</h3>${stages.map((s,j)=>`<a href="#lesson/${j}" class="${j===i?'current':''}" ${j===i?'aria-current="step"':''}><span>${state.completed.includes(j)?'✓':String(j+1).padStart(2,'0')}</span>${s[0]}</a>`).join('')}<p class="meta">${state.completed.length} of 9 complete<br>Your exercise drafts save as you write.</p><a href="#notebook/draft" class="text-link">View proposal draft ${icon('arrow')}</a></aside><article class="lesson-main"><div class="lesson-title"><div class="lesson-visual" aria-hidden="true"></div><p class="eyebrow">${phases[c.phase].label} / LESSON ${String(i+1).padStart(2,'0')}</p><h1>${c.title}</h1><p>${c.subtitle}</p><div class="lesson-title-meta"><span>${c.time} min suggested activity</span><span>Output: ${c.output}</span></div></div><div class="lesson-content">${c.sections.map(([h,p])=>`<section><h2>${h}</h2><p>${p}</p></section>`).join('')}<div class="example"><h3>See the difference</h3><p class="meta">Illustrative example · Not a claim about a real study</p><div class="example-pair"><div><small>A starting point</small><p>${c.before}</p></div><div><small>A more useful direction</small><p>${c.after}</p></div></div><p>${c.example}</p></div><div class="pitfall"><strong>A common pitfall</strong><p>${c.trap}</p></div><section><h2>Put it into practice</h2><ol class="steps">${c.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section></div><section class="exercise" id="exercise"><p class="eyebrow">YOUR TURN</p><h2>${c.output}</h2><p>${c.prompt}</p><label for="exercise-text">Your working draft</label><textarea id="exercise-text" rows="9" data-stage="${i}" maxlength="100000" placeholder="${esc(c.placeholder)}">${esc(state.drafts[i]||'')}</textarea><div class="field-foot"><span id="draft-status" role="status">${storageAvailable?'Saved on this device as you type':'Storage unavailable — export before leaving'}</span><span id="word-count">${wordCount(state.drafts[i]||'')} words</span></div><a class="text-link" href="#notebook/draft">See this in your proposal draft ${icon('up')}</a><form id="quiz-form" class="quiz" data-stage="${i}"><h3>Check your understanding</h3><fieldset><legend>${c.question}</legend>${c.answers.map((a,n)=>`<label><input type="radio" name="answer" value="${n}" ${state.quiz[i]===n?'checked':''}>${a}</label>`).join('')}</fieldset><button class="button secondary small" type="submit">Check answer</button><div id="quiz-feedback" role="status">${state.quiz[i]!==undefined?quizFeedback(i,state.quiz[i]):''}</div></form><div class="completion-bar"><div><strong id="completion-label">${isDone?'Milestone complete':'Ready to move forward?'}</strong><p>Save a draft and answer the check correctly.</p></div><button class="button ${isDone?'secondary':'primary'}" data-complete="${i}">${isDone?'Reopen milestone':'Complete milestone'} ${icon('check')}</button></div><div class="actions">${i>0?`<a class="text-link" href="#lesson/${i-1}">← Previous lesson</a>`:''}<a class="text-link" style="margin-left:auto" href="${i<8?'#lesson/'+(i+1):'#notebook/draft'}">${i<8?'Next: '+stages[i+1][0]:'Review your proposal draft'} ${icon('arrow')}</a></div></section></article></div></div>`}
function quizFeedback(i,a){return `<div class="quiz-feedback ${a===course[i].correct?'':'wrong'}"><strong>${a===course[i].correct?'That’s right.':'Try again.'}</strong> ${course[i].feedback}</div>`}
function resourceCards(){const found=resources.filter(r=>(toolFilter==='All'||r.category===toolFilter)&&(r.name+' '+r.desc).toLowerCase().includes(toolQuery.toLowerCase()));const outcomes={proposal:['Shape the argument','A guided proposal outline'],matrix:['Compare the evidence','A reusable comparison sheet'],search:['Search with intention','A documented search strategy'],framework:['Connect your concepts','A framework you can explain'],methods:['Design a feasible study','A practical methods plan'],checklist:['Prepare for feedback','A structured review checklist']};return found.length?found.map(r=>{const i=resources.indexOf(r),copy=outcomes[r.id]||['Develop your research',r.name];return `<article class="resource-card resource-instrument"><div class="resource-index"><span>0${i+1}</span><small>${r.category}</small></div><a class="resource-art" href="#resource/${r.id}" aria-label="Open ${esc(r.name)}">${phaseArt(r.category==='Writing'?2:r.category==='Evidence'?1:0)}</a><div class="resource-copy"><p class="eyebrow">${copy[0]}</p><h3><a href="#resource/${r.id}">${r.name}</a></h3><p>${r.desc}</p><div class="resource-spec"><span>YOUR OUTPUT</span><strong>${copy[1]}</strong><span>${r.format} · EDITABLE</span></div><div class="actions"><a class="button primary" href="#resource/${r.id}">Explore this tool ${icon('arrow')}</a><button class="text-button" data-download="${r.id}" aria-label="Download ${esc(r.name)}">Download ${r.format} ${icon('download')}</button></div></div></article>`}).join(''):'<div class="no-results"><h3>No matching resources.</h3><p>Try a different search or choose All resources.</p></div>'}
function toolkit(){return `<div class="container">${heading('RESEARCH TOOLKIT','Good thinking deserves good tools.','Six editable resources to organize your evidence, plan your study, and prepare for feedback.')}<div class="page-body"><div class="toolbar"><div class="tabs" aria-label="Filter resources">${['All','Planning','Evidence','Writing'].map(x=>`<button data-tool-filter="${x}" aria-pressed="${toolFilter===x}">${x==='All'?'All resources':x}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="resource-search" type="search" placeholder="Find a resource…" aria-label="Search resources" value="${esc(toolQuery)}"></label></div><div class="resource-grid" id="resource-grid">${resourceCards()}</div><div class="info-line">${icon('info')}<div><strong>Make these your own.</strong> CSV files open in spreadsheet applications. Markdown (MD) files open in a text editor and can be copied into your preferred document tool. Adapt the structure to your institution’s requirements.</div></div></div></div>`}
function wordCount(s){return s.trim()?s.trim().split(/\s+/).length:0}
function notesHtml(){const found=state.notes.filter(n=>(n.title+' '+n.body+' '+stages[n.stage][0]).toLowerCase().includes(noteQuery.toLowerCase()));return found.length?found.map(n=>`<article class="note"><span class="pill ${phases[course[n.stage].phase].color}">${stages[n.stage][0]}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="note-footer"><span>${validDate(n.updated||n.created)} · ${wordCount(n.body)} words</span><div><button class="text-button" data-edit="${esc(n.id)}">${icon('edit')}Edit</button><button class="text-button" data-delete="${esc(n.id)}" aria-label="Delete ${esc(n.title)}">${icon('trash')}</button></div></div></article>`).join(''):`<div class="empty-state">${icon('notebook')}<h3>${noteQuery?'No ideas found.':'Give your ideas a place to grow.'}</h3><p>${noteQuery?'Try another word or clear your search.':'Capture a question, a useful source, or a connection you don’t want to lose. Your saved ideas will appear here.'}</p>${!noteQuery?'<a class="text-link" href="#lesson/0">Need a starting prompt? Explore lesson 1 →</a>':''}</div>`}
function validDate(s){const d=new Date(s);return Number.isNaN(d.getTime())?'Saved idea':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function noteEditor(){const n=editing?(state.editDraft?.id===editing?state.editDraft:state.notes.find(x=>x.id===editing)):state.noteDraft;return `<form id="note-form" class="editor"><p class="eyebrow">IDEA NOTEBOOK</p><h2>${editing?'Refine your idea':'Capture a new idea'}</h2><p>Questions, observations, sources, and unfinished thoughts belong here.</p><label for="note-title">Title</label><input id="note-title" maxlength="150" required placeholder="A question I keep coming back to…" value="${esc(n?.title||'')}"><label for="note-stage">Related milestone</label><select id="note-stage">${stages.map((s,i)=>`<option value="${i}" ${n?.stage===i?'selected':''}>${String(i+1).padStart(2,'0')} · ${s[0]}</option>`).join('')}</select><label for="note-body">Your thinking</label><textarea id="note-body" rows="8" maxlength="100000" required placeholder="What have you noticed? What could it mean? Include a source or link if you have one.">${esc(n?.body||'')}</textarea><div class="actions"><button class="button primary" type="submit">${editing?'Save changes':'Save idea'} ${icon(editing?'check':'plus')}</button>${editing?'<button class="button secondary" type="button" data-action="cancel-edit">Cancel</button>':''}</div><p class="site-note" id="note-status" role="status">${editing?'An unfinished copy is saved locally. Save changes to update the idea.':'Unfinished new notes are saved locally as you type.'}</p></form>`}
function draftHtml(){const count=Object.values(state.drafts).filter(x=>x.trim()).length;return `<div class="draft-layout"><aside class="draft-outline"><h3>Your proposal outline</h3>${stages.map((s,i)=>`<a href="#notebook/draft" data-scroll="draft-${i}"><span>${i+1}. ${s[0]}</span><span>${state.drafts[i]?.trim()?'✓':'—'}</span></a>`).join('')}<a class="text-link" href="#notebook/readiness">Review readiness →</a></aside><article class="draft-paper"><p class="eyebrow">MY RESEARCH / WORKING DRAFT</p><h2>A proposal taking shape.</h2><p class="meta">${count} of 9 sections started · Built from your lesson exercises.<br>This is a working outline. Refine its structure and references before submission.</p>${stages.map((s,i)=>`<section class="draft-section" id="draft-${i}"><h3>${String(i+1).padStart(2,'0')} / ${s[0]}<a href="#lesson/${i}/write">${state.drafts[i]?.trim()?'Edit draft':'Start writing'} ↗</a></h3><p class="${state.drafts[i]?.trim()?'':'unwritten'}">${state.drafts[i]?.trim()?esc(state.drafts[i]):course[i].prompt}</p></section>`).join('')}</article></div>`}
function readinessHtml(){return `<div class="readiness"><div class="editor"><p class="eyebrow">BEFORE YOU SHARE</p><h2>Review the whole argument.</h2><p>This is a self-review, not institutional approval. Check each statement only when it is supported by your draft.</p><strong id="readiness-count">${state.checks.length} of 27 checks complete</strong><div class="check-progress"><span id="check-progress" style="width:${state.checks.length/27*100}%"></span></div></div>${course.map((c,i)=>`<section class="check-group"><h3>${String(i+1).padStart(2,'0')} / ${stages[i][0]}</h3>${c.checks.map((s,j)=>`<label><input type="checkbox" data-readiness="${i}-${j}" ${state.checks.includes(i+'-'+j)?'checked':''}>${s}</label>`).join('')}</section>`).join('')}<div class="info-line">${icon('people')}<div><strong>Get another perspective.</strong> Ask your supervisor or a peer to review the connections between the problem, question, objectives, and methods. Record their feedback in your notebook.</div></div></div>`}
function workspace(){return `<div class="container">${heading('YOUR RESEARCH WORKSPACE','Keep your thinking connected.','Capture ideas, build your proposal, and return to the questions that matter.',`<button class="button secondary small" data-action="backup">Backup ${icon('download')}</button><button class="button secondary small" data-action="import">Restore backup</button><button class="button primary small" data-action="export">Export ${workspaceTab==='notes'?'notebook':workspaceTab==='draft'?'draft':'checklist'} ${icon('download')}</button>`)}<div class="page-body"><div class="workspace-tabs" aria-label="Workspace views">${[['notes','Idea notebook'],['draft','Proposal draft'],['readiness','Readiness check']].map(([v,l])=>`<button data-workspace="${v}" aria-pressed="${v===workspaceTab}">${l}</button>`).join('')}</div>${workspaceTab==='notes'?`<div class="workspace-grid"><div id="editor-wrap">${noteEditor()}</div><div><div class="notes-toolbar"><label class="searchbox">${icon('search')}<input id="note-search" type="search" placeholder="Search your ideas…" aria-label="Search notes" value="${esc(noteQuery)}"></label><span id="notes-total">${state.notes.length} ${state.notes.length===1?'idea':'ideas'}</span></div><div id="note-list" class="note-list">${notesHtml()}</div></div></div>`:workspaceTab==='draft'?draftHtml():readinessHtml()}<p class="site-note">${icon('shield')} Saved in this browser only. Download a backup to move your work to another device or keep a separate copy.</p></div></div>`}
function seminars(){return `<div class="container">${heading('SEMINARS & GUIDED WORKSHOPS','Make space for deeper thinking.','Use a focused workshop to move one part of your research forward, on your own or with a study group.')}<div class="page-body"><div class="workshop-banner">${icon('people')}<div><p class="eyebrow" style="color:var(--mint)">SELF-GUIDED WORKSHOPS</p><h2>A useful hour. A tangible next step.</h2><p>These structured sessions combine academy lessons with timed activities and discussion prompts. No registration or recording required.</p></div></div><div class="workshop-grid">${phases.map((p,i)=>`<article class="workshop"><span class="pill ${p.color}">WORKSHOP 0${i+1} · 45–60 MIN</span><h3>${p.name}</h3><p>${p.desc}</p><ul>${course.slice(i*3,i*3+3).map(c=>`<li>${c.output}</li>`).join('')}</ul><button class="button secondary full" data-workshop="${i}">Open workshop guide ${icon('arrow')}</button></article>`).join('')}</div><div class="archive-empty">${icon('book')}<div><h3>Seminar recording archive</h3><p>No event recordings or slide decks have been supplied yet. The self-guided workshops above are available now.</p></div></div>${readings()}</div></div>`}
let currentRoute='';
function route(){if(window.rrhBeforeRoute)window.rrhBeforeRoute();if(window.stopUniverse)window.stopUniverse();const parts=location.hash.slice(1).split('/');const page=parts[0]||'home';if(page==='main'){history.replaceState(null,'','#home');$('#main').focus();return}if($('#modal').open)$('#modal').close();$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation');let html,title,mounted=Promise.resolve();switch(page){case 'research':html=window.REIResearch.shell();title='Research studio';break;case 'home':html=home();title='Your next discovery starts here';break;case 'journey':html=journey();title='Research journey';break;case 'academy':html=academy();title='Academy';break;case 'lesson':{const i=Number(parts[1]);if(!Number.isInteger(i)||i<0||i>8){location.hash='academy';return}html=lesson(i,parts[2]);title=course[i].title+' — '+({learn:'Learn',example:'Example',write:'Write',check:'Check'}[parts[2]||'learn']||'Learn');break}case 'resource':html=resourcePage(parts[1]);title='Resource guide';break;case 'workshop':{const i=Number(parts[1]);if(!Number.isInteger(i)||i<0||i>2){location.hash='seminars';return}html=workshopPage(i);title=phases[i].name;break}case 'toolkit':html=toolkit();title='Research toolkit';break;case 'notebook':workspaceTab=['draft','readiness'].includes(parts[1])?parts[1]:'notes';html=workspace();title='My workspace';break;case 'seminars':html=seminars();title='Seminars & workshops';break;default:location.hash='home';return}$('#main').innerHTML=html;document.title=title+' · REI';document.querySelectorAll('#navigation a').forEach(a=>{if(a.hash==='#'+(page==='lesson'?'academy':page==='resource'?'toolkit':page==='workshop'?'seminars':page))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#note-count').textContent=state.notes.length;currentRoute=page;document.body.dataset.page=page;hydrateIcons();window.scrollTo({top:0,behavior:'instant'});if(page==='research')mounted=window.REIResearch.mount(parts);if(page==='home'&&window.startUniverse)window.startUniverse();window.dispatchEvent(new CustomEvent('rrh:route',{detail:{page}}));if(!storageAvailable)toast('Browser storage is unavailable. Back up your work before leaving.');return mounted}
window.addEventListener('hashchange',()=>{if(window.rrhNavigate)window.rrhNavigate(route);else{route();$('#main').focus({preventScroll:true})}});
function download(name,text,type='text/markdown;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function showModal(html){$('#modal-content').innerHTML=html;hydrateIcons();$('#modal').showModal();$('#modal').scrollTop=0}
function refreshNotes(){if($('#note-list'))$('#note-list').innerHTML=notesHtml();if($('#notes-total'))$('#notes-total').textContent=state.notes.length+(state.notes.length===1?' idea':' ideas');$('#note-count').textContent=state.notes.length}
function exportText(){if(workspaceTab==='draft')return '# My research proposal working draft\n\nThis outline contains my saved lesson exercises. Review structure, sources, and institutional requirements before submission.\n\n'+stages.map((s,i)=>`## ${i+1}. ${s[0]}\n\n${state.drafts[i]?.trim()||'[Not yet drafted]'}\n`).join('\n');if(workspaceTab==='readiness')return '# Proposal readiness self-review\n\n'+course.map((c,i)=>'## '+stages[i][0]+'\n'+c.checks.map((s,j)=>`- [${state.checks.includes(i+'-'+j)?'x':' '}] ${s}`).join('\n')).join('\n\n');return '# My research notebook\n\n'+state.notes.map(n=>`## ${n.title}\nMilestone: ${stages[n.stage][0]}\n\n${n.body}\n`).join('\n---\n\n')}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.classList.contains('skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return}if(b.closest('#navigation')&&b.tagName==='A'){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation')}if(b.classList.contains('menu-toggle')){const opened=$('#navigation').classList.toggle('open');b.setAttribute('aria-expanded',opened);b.setAttribute('aria-label',opened?'Close navigation':'Open navigation');return}if(b.classList.contains('modal-close')){$('#modal').close();return}if(b.dataset.courseFilter!==undefined){academyFilter=b.dataset.courseFilter;document.querySelectorAll('[data-course-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#lesson-grid').innerHTML=lessonCards()}if(b.dataset.toolFilter){toolFilter=b.dataset.toolFilter;document.querySelectorAll('[data-tool-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#resource-grid').innerHTML=resourceCards()}if(b.dataset.workspace){location.hash='notebook'+(b.dataset.workspace==='notes'?'':'/'+b.dataset.workspace)}if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}if(b.dataset.download){const r=resources.find(x=>x.id===b.dataset.download);if(r){download('research-'+r.id+'.'+r.format.toLowerCase(),r.content,r.format==='CSV'?'text/csv;charset=utf-8':'text/markdown;charset=utf-8');toast('Your resource is ready to download.')}}if(b.dataset.resource){location.hash='resource/'+b.dataset.resource;return}if(b.dataset.complete!==undefined){const i=+b.dataset.complete;if(state.completed.includes(i)){state.completed=state.completed.filter(x=>x!==i);save();b.innerHTML='Complete milestone '+icon('check');b.className='button primary';$('#completion-label').textContent='Ready to move forward?';toast('Milestone reopened. Your writing is unchanged.')}else{if(!state.drafts[i]?.trim()){toast('Write a working draft before completing this milestone.');if($('#exercise-text'))$('#exercise-text').focus();else location.hash='lesson/'+i+'/write';return}if(state.quiz[i]!==course[i].correct){toast('Check your answer before completing this milestone.');$('#quiz-form input').focus();return}state.completed.push(i);save();b.innerHTML='Reopen milestone '+icon('check');b.className='button secondary';$('#completion-label').textContent='Milestone complete';toast(i===8?'All set for a proposal review.':'Milestone complete. Your next lesson is ready.')}}if(b.dataset.complete!==undefined&&$('.lesson-sidebar .meta')){$('.lesson-sidebar .meta').innerHTML=state.completed.length+' of 9 complete<br>Your exercise drafts save as you write.';const n=$('.lesson-sidebar a.current>span');if(n)n.textContent=state.completed.includes(+b.dataset.complete)?'✓':String(+b.dataset.complete+1).padStart(2,'0')}if(b.dataset.edit){if(editing&&state.editDraft&&editing!==b.dataset.edit){toast('Save or cancel the idea you are editing first.');$('#note-title').focus();return}editing=b.dataset.edit;$('#editor-wrap').innerHTML=noteEditor();$('#note-title').focus();$('#editor-wrap').scrollIntoView({block:'start',behavior:'smooth'})}if(b.dataset.delete){const n=state.notes.find(x=>x.id===b.dataset.delete);showModal(`<p class="eyebrow">REMOVE IDEA</p><h2>Delete this idea?</h2><p>“${esc(n.title)}” will be removed from your notebook. Your lesson drafts are separate.</p><div class="actions"><button class="button danger" data-confirm-delete="${esc(n.id)}">Delete idea</button><button class="button secondary" data-action="close">Keep idea</button></div>`)}if(b.dataset.confirmDelete){const idx=state.notes.findIndex(x=>x.id===b.dataset.confirmDelete);if(idx>=0){deleted={note:state.notes[idx],index:idx};state.notes.splice(idx,1);if(editing===deleted.note.id){editing=null;state.editDraft=null;$('#editor-wrap').innerHTML=noteEditor()}save();refreshNotes();$('#modal').close();toast('Idea deleted.',true)}}if(b.dataset.workshop!==undefined){location.hash='workshop/'+b.dataset.workshop;return}if(b.dataset.workshopDownload!==undefined){const i=+b.dataset.workshopDownload;download('workshop-'+(i+1)+'.md','# '+phases[i].name+'\nSelf-guided workshop · 45–60 minutes\n\n5 min: Set an intention.\n\n'+course.slice(i*3,i*3+3).map(c=>'10–15 min: '+c.title+'\n'+c.prompt).join('\n\n')+'\n\n10 min: Review assumptions, record uncertainties, and choose a next action.')}const action=b.dataset.action;if(action==='close')$('#modal').close();if(action==='cancel-edit'){editing=null;state.editDraft=null;save();$('#editor-wrap').innerHTML=noteEditor()}if(action==='undo'&&deleted){state.notes.splice(Math.min(deleted.index,state.notes.length),0,deleted.note);deleted=null;save();refreshNotes();toast('Idea restored.')}if(action==='export'){download('research-'+workspaceTab+'.md',exportText());toast('Your '+(workspaceTab==='draft'?'proposal draft':'workspace export')+' is ready.')}if(action==='backup'){download('research-ready-backup.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2),'application/json');toast('Backup includes notes, drafts, and progress.')}if(action==='import'){showModal('<p class="eyebrow">RESTORE YOUR WORKSPACE</p><h2>Open a saved backup.</h2><p>Choose a REI JSON backup. You can review it before replacing your current workspace.</p><label for="backup-file">Backup file</label><input type="file" id="backup-file" accept=".json,application/json"><div id="import-preview" role="status"></div>')}if(action==='confirm-import'&&pendingImport){state=pendingImport;pendingImport=null;editing=state.editDraft?.id||null;save();$('#modal').close();route();toast('Workspace restored from your backup.')}if(action==='about')showModal('<p class="eyebrow">ABOUT REI</p><h2>A practical foundation for student research.</h2><p>This hub helps you move from an initial interest to a coherent proposal through nine lessons, writing activities, and reusable resources.</p><p>The examples are illustrative and the activities are self-guided. The hub does not grade your work, verify references, or replace academic supervision.</p><p>Accounts, cross-device sync, an AI mentor, and community features are future possibilities. They are not active services in this version.</p>');if(action==='privacy')showModal('<p class="eyebrow">YOUR DATA</p><h2>Your work stays in this browser.</h2><p>Notes, drafts, answers, and progress are stored locally on this device. There is no account or automatic cross-device synchronization.</p><p>Clearing browser data or using a different browser can remove access to your work. Download a JSON backup from My workspace to preserve or move it. Markdown exports are readable copies; JSON backups restore the workspace.</p><p>Anyone using this browser profile may be able to read your saved work. Avoid storing identifiable participant data here. The interface’s fonts are included with the site; no external font service is needed.</p>')});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='lesson-search'){academyQuery=el.value;$('#lesson-grid').innerHTML=lessonCards()}if(el.id==='resource-search'){toolQuery=el.value;$('#resource-grid').innerHTML=resourceCards()}if(el.id==='note-search'){noteQuery=el.value;refreshNotes()}if(el.id==='exercise-text'){state.drafts[+el.dataset.stage]=el.value;const ok=save();$('#draft-status').textContent=ok?'Saved on this device':'Not saved — export your work before leaving';$('#word-count').textContent=wordCount(el.value)+' words'}if(['note-title','note-body','note-stage'].includes(el.id)){const working={title:$('#note-title').value,body:$('#note-body').value,stage:+$('#note-stage').value};if(editing)state.editDraft={...working,id:editing};else state.noteDraft=working;const ok=save();$('#note-status').textContent=ok?'Unfinished note saved on this device.':'Storage unavailable. Copy or export your work before leaving.'}});
document.addEventListener('change',async e=>{if(e.target.dataset.readiness){const k=e.target.dataset.readiness;state.checks=e.target.checked?[...new Set([...state.checks,k])]:state.checks.filter(x=>x!==k);save();$('#readiness-count').textContent=state.checks.length+' of 27 checks complete';$('#check-progress').style.width=state.checks.length/27*100+'%'}if(e.target.id==='backup-file'){pendingImport=null;try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Choose a backup smaller than 5 MB.');const raw=JSON.parse(await f.text());if(raw.version!==2||!Array.isArray(raw.notes)||!Array.isArray(raw.completed)||!raw.drafts||typeof raw.drafts!=='object')throw Error('This is not a supported REI backup.');pendingImport=sanitize(raw);$('#import-preview').innerHTML=`<p><strong>${pendingImport.notes.length} ideas, ${Object.keys(pendingImport.drafts).length} drafts, ${pendingImport.completed.length} completed milestones.</strong></p><p>Restoring replaces this browser’s current workspace. Download a backup first if you want to keep it.</p><div class="actions"><button class="button secondary" data-action="backup">Back up current workspace</button><button class="button primary" data-action="confirm-import">Replace and restore</button></div>`}catch(err){$('#import-preview').textContent='Could not read the backup. '+err.message}}});
document.addEventListener('submit',e=>{if(e.target.id==='quiz-form'){e.preventDefault();const i=+e.target.dataset.stage,answer=new FormData(e.target).get('answer');if(answer===null){$('#quiz-feedback').innerHTML='<div class="quiz-feedback wrong">Choose an answer first.</div>';return}state.quiz[i]=+answer;save();$('#quiz-feedback').innerHTML=quizFeedback(i,+answer)}if(e.target.id==='note-form'){e.preventDefault();const title=$('#note-title').value.trim(),body=$('#note-body').value.trim(),stage=+$('#note-stage').value;if(!title||!body){$('#note-status').textContent='Add a title and your thinking before saving.';return}if(editing){const n=state.notes.find(x=>x.id===editing);if(n)Object.assign(n,{title,body,stage,updated:new Date().toISOString()});editing=null;state.editDraft=null}else{state.notes.unshift({id:uid(),title,body,stage,created:new Date().toISOString(),updated:null});state.noteDraft={title:'',body:'',stage:0}}const ok=save();$('#editor-wrap').innerHTML=noteEditor();refreshNotes();toast(ok?'Idea saved to your notebook.':'Idea kept for this session. Export a backup to keep it.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}});
$('#modal').addEventListener('click',e=>{if(e.target!==$('#modal'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()});
hydrateIcons();route();
